/bin/zsh -lc "command -v python3; command -v rsvg-convert; command -v convert; command -v magick; command -v dot; python3 - <<'PY'
mods=['PIL','cairosvg']
for m in mods:
 try:
  x=__import__(m); print(m,'ok',getattr(x,'__version__',''))
 except Exception as e: print(m,'missing',e)
PY
fc-list | sed -n '1,20p'"

